lessons.push(...[{"subject": "商業簿記", "topic": "為替換算会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=80", "sourceLabel": "外貨建取引等会計処理基準 一2(1)③ハ・ニ、一3", "reviewed": "2026-11-14", "years": [2026, 2027], "id": "fx-20261114-01", "title": "外貨建子会社株式の期末換算", "body": "親会社の個別財務諸表を考えます。評価額の引下げを要する事情がない子会社株式は、期末の為替だけで取得原価を換算し直しません。在外子会社の財務諸表を連結のために換算する処理とは別です。", "tag": "外貨建株式・翌期決済"}, {"subject": "商業簿記", "topic": "為替換算会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=80", "sourceLabel": "外貨建取引等会計処理基準 一2(1)③ハ・ニ、一3", "reviewed": "2026-11-14", "years": [2026, 2027], "id": "fx-20261114-02", "title": "子会社株式と為替の数値例", "body": "子会社株式をUSD2,000、取得時140円で取得。個別財務諸表で評価額引下げの事情なしなら、期末150円でも280,000円のままです。20,000円の為替益を機械的に計上しません。", "tag": "外貨建株式・翌期決済"}, {"subject": "商業簿記", "topic": "為替換算会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=80", "sourceLabel": "外貨建取引等会計処理基準 一2(1)③ハ・ニ、一3", "reviewed": "2026-11-14", "years": [2026, 2027], "id": "fx-20261114-03", "title": "関連会社株式の換算", "body": "関連会社株式も、個別財務諸表では取得時の相場を使う対象です。USD1,500を142円で取得し、評価額引下げの事情がなければ、期末148円でも213,000円です。", "tag": "外貨建株式・翌期決済"}, {"subject": "商業簿記", "topic": "為替換算会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=80", "sourceLabel": "外貨建取引等会計処理基準 一2(1)③ハ・ニ、一3", "reviewed": "2026-11-14", "years": [2026, 2027], "id": "fx-20261114-04", "title": "換算原則と評価額引下げの区別", "body": "取得時相場という原則を、評価額引下げの判断不要という意味にしないでください。時価の著しい下落や実質価額の著しい低下がある場合は別途検討します。ここでの数値例は、その事情がない場合だけを扱います。", "tag": "外貨建株式・翌期決済"}, {"subject": "商業簿記", "topic": "為替換算会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=80", "sourceLabel": "外貨建取引等会計処理基準 一2(1)③ハ・ニ、一3", "reviewed": "2026-11-14", "years": [2026, 2027], "id": "fx-20261114-05", "title": "翌期回収は前期末の帳簿額から", "body": "ヘッジなしの売掛金USD1,000を140円で計上し、前期末150円で150,000円に換算済み。翌期148円で全額回収すると148,000円を受け取り、翌期の為替差損は2,000円です。前期の為替益10,000円を再計上しません。", "tag": "外貨建株式・翌期決済"}, {"subject": "商業簿記", "topic": "為替換算会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=80", "sourceLabel": "外貨建取引等会計処理基準 一2(1)③ハ・ニ、一3", "reviewed": "2026-11-14", "years": [2026, 2027], "id": "fx-20261114-06", "title": "翌期支払と為替差益", "body": "ヘッジなしの買掛金USD1,000は、前期末150円で150,000円に換算済み。翌期148円で全額支払うと、債務150,000円を148,000円で消滅させ、翌期の為替差益は2,000円です。", "tag": "外貨建株式・翌期決済"}, {"subject": "商業簿記", "topic": "為替換算会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=80", "sourceLabel": "外貨建取引等会計処理基準 一2(1)③ハ・ニ、一3", "reviewed": "2026-11-14", "years": [2026, 2027], "id": "fx-20261114-07", "title": "前期の損失と翌期の利益を分ける", "body": "売掛金USD1,000、発生時140円、前期末135円、翌期回収142円、ヘッジなし。前期は差損5,000円、翌期は差益7,000円です。全期間の差益2,000円と、各年度の損益は区別します。", "tag": "外貨建株式・翌期決済"}, {"subject": "商業簿記", "topic": "為替換算会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=80", "sourceLabel": "外貨建取引等会計処理基準 一2(1)③ハ・ニ、一3", "reviewed": "2026-11-14", "years": [2026, 2027], "id": "fx-20261114-08", "title": "債務の翌期差損と決済仕訳", "body": "買掛金USD1,000を前期末145円で換算済み。翌期149円で全額支払う場合、借方：買掛金145,000円・為替差損4,000円、貸方：現金預金149,000円です。借方と貸方は一致します。", "tag": "外貨建株式・翌期決済"}]);
qs.push(...[{"subject": "商業簿記", "topic": "為替換算会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=80", "sourceLabel": "外貨建取引等会計処理基準 一2(1)③ハ・ニ、一3", "reviewed": "2026-11-14", "years": [2026, 2027], "id": "fx-q-20261114-01", "q": "個別財務諸表で取得原価計上の外貨建子会社株式。減損等の事情なし。期末の換算相場は？", "a": ["取得時の相場", "期末相場", "翌期の相場"], "correct": 0, "ex": "外国通貨の金銭債権と子会社株式を区別します。条件上は取得時の相場です。"}, {"subject": "商業簿記", "topic": "為替換算会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=80", "sourceLabel": "外貨建取引等会計処理基準 一2(1)③ハ・ニ、一3", "reviewed": "2026-11-14", "years": [2026, 2027], "id": "fx-q-20261114-02", "q": "子会社株式USD3,000を145円で取得。期末155円、評価額引下げの事情なし。個別財務諸表の円額は？", "a": ["465,000円", "435,000円", "30,000円"], "correct": 1, "ex": "3,000×取得時145＝435,000円。期末相場への一律換算はしません。"}, {"subject": "商業簿記", "topic": "為替換算会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=80", "sourceLabel": "外貨建取引等会計処理基準 一2(1)③ハ・ニ、一3", "reviewed": "2026-11-14", "years": [2026, 2027], "id": "fx-q-20261114-03", "q": "関連会社株式USD4,000を138円で取得。期末146円、評価額引下げの事情なし。個別財務諸表の円額は？", "a": ["584,000円", "552,000円", "32,000円"], "correct": 1, "ex": "4,000×138＝552,000円。売買目的有価証券の時価換算とは区別します。"}, {"subject": "商業簿記", "topic": "為替換算会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=80", "sourceLabel": "外貨建取引等会計処理基準 一2(1)③ハ・ニ、一3", "reviewed": "2026-11-14", "years": [2026, 2027], "id": "fx-q-20261114-04", "q": "外貨建子会社株式の評価額を引き下げるべき事情が生じた。正しい読み方は？", "a": ["取得時相場の原則があるので検討不要", "為替差額だけを必ず純資産へ計上", "評価額引下げの規則を別途検討する"], "correct": 2, "ex": "取得時相場という原則だけで、評価額引下げの要否まで免除されるわけではありません。"}, {"subject": "商業簿記", "topic": "為替換算会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=80", "sourceLabel": "外貨建取引等会計処理基準 一2(1)③ハ・ニ、一3", "reviewed": "2026-11-14", "years": [2026, 2027], "id": "fx-q-20261114-05", "q": "売掛金USD2,000を140円で計上、前期末150円で換算済み。翌期148円で全額回収、ヘッジなし。翌期の為替損益は？", "a": ["差損4,000円", "差益16,000円", "差益20,000円"], "correct": 0, "ex": "前期末300,000円に対して回収296,000円。翌期の差損は4,000円です。"}, {"subject": "商業簿記", "topic": "為替換算会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=80", "sourceLabel": "外貨建取引等会計処理基準 一2(1)③ハ・ニ、一3", "reviewed": "2026-11-14", "years": [2026, 2027], "id": "fx-q-20261114-06", "q": "買掛金USD3,000を142円で計上、前期末150円で換算済み。翌期147円で全額支払、ヘッジなし。翌期の為替損益は？", "a": ["差損15,000円", "差益9,000円", "差益24,000円"], "correct": 1, "ex": "帳簿債務450,000円−支払441,000円＝差益9,000円。取得時142円からの全変動を翌期に計上しません。"}, {"subject": "商業簿記", "topic": "為替換算会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=80", "sourceLabel": "外貨建取引等会計処理基準 一2(1)③ハ・ニ、一3", "reviewed": "2026-11-14", "years": [2026, 2027], "id": "fx-q-20261114-07", "q": "売掛金USD800、発生時140円、前期末135円、翌期回収142円。ヘッジなし。翌期だけの為替損益は？", "a": ["差益1,600円", "差損4,000円", "差益5,600円"], "correct": 2, "ex": "翌期は800×（142−135）＝差益5,600円。発生時からの差益1,600円とは別です。"}, {"subject": "商業簿記", "topic": "為替換算会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=80", "sourceLabel": "外貨建取引等会計処理基準 一2(1)③ハ・ニ、一3", "reviewed": "2026-11-14", "years": [2026, 2027], "id": "fx-q-20261114-08", "q": "買掛金USD1,200は前期末145円で換算済み。翌期149円で全額支払、ヘッジなし。翌期の仕訳は？", "a": ["借：買掛金174,000・為替差損4,800／貸：現金預金178,800", "借：買掛金178,800／貸：現金預金174,000・為替差益4,800", "借：買掛金174,000／貸：現金預金174,000"], "correct": 0, "ex": "1,200×145＝174,000円、支払は1,200×149＝178,800円。差額4,800円は為替差損です。"}]);
